<template>
  <view class="services-page">
    <AppHeader />
    <section class="services-hero" :style="heroStyle">
      <view class="hero-overlay" />
      <PageContainer wide>
        <view class="hero-content"><text class="eyebrow">SMART SERVICES</text><text class="hero-title">需要的服务，就在最近处</text><text class="hero-copy">设施状态、服务时间与位置描述实时可查。</text></view>
        <view class="filter-dock"><scroll-view class="category-scroll" scroll-x :show-scrollbar="false"><view class="categories"><text v-for="item in categories" :key="item" class="category" :class="{ active: category === item }" @tap="category = item">{{ item }}</text></view></scroll-view><view class="nearby" :class="{ active: nearbyFirst }" @tap="nearbyFirst = !nearbyFirst"><text>◎</text><text>附近优先</text></view></view>
      </PageContainer>
    </section>
    <main class="facility-section"><PageContainer wide>
      <view class="section-head"><view><text class="section-kicker">{{ cityName }} · SERVICE DISCOVERY</text><text class="section-title">旅行服务设施</text></view><view class="source-note"><text class="source-dot" :class="`source-dot--${sourceMode}`" /><text>{{ sourceLabel }}</text></view></view>
      <view v-if="loading" class="empty-state"><text>正在加载服务设施…</text></view>
      <view v-else-if="error" class="empty-state empty-state--error"><text>{{ error }}</text></view>
      <view v-else-if="!visibleFacilities.length" class="empty-state"><text class="empty-title">暂未找到附近的「{{ category }}」</text><text>可以尝试切换其他服务类型</text><button @tap="category = '全部设施'">查看全部设施</button></view>
      <view v-else class="facility-grid"><article v-for="facility in visibleFacilities" :key="facility.id" class="facility-card" @tap="openFacility(facility)"><view class="card-top"><view class="facility-icon">{{ iconFor(facility.type) }}</view><text class="status" :class="`status--${facility.status.toLowerCase()}`">{{ statusLabel(facility.status) }}</text></view><text class="facility-name">{{ facility.name }}</text><text class="facility-description">{{ facility.description }}</text><view class="divider" /><view class="detail"><text class="detail-icon">⌖</text><text>{{ facility.location }}</text></view><view class="detail"><text class="detail-icon">◉</text><text>{{ distanceLabel(facility) }}</text></view><view class="detail"><text class="detail-icon">◷</text><text>服务时间：{{ facility.openingHours }}</text></view><view class="card-footer"><text>{{ facility.source === 'amap' ? '高德服务数据' : facility.source === 'local' ? '景区本地资料' : '本地备用资料' }}</text><text v-if="facility.latitude != null">查看位置 →</text></view></article></view>
    </PageContainer></main>
  </view>
</template>

<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue';
import AppHeader from '../../components/layout/AppHeader.vue';
import PageContainer from '../../components/layout/PageContainer.vue';
import { initializeCityContext } from '../../composables/useCityContext';
import { useTouristStore } from '../../stores';
import { loadServiceFacilities, type FacilityStatus, type ServiceFacility } from '../../services/serviceFacilityService';

const store = useTouristStore(); const loading = ref(true); const error = ref(''); const category = ref('全部设施'); const nearbyFirst = ref(false); const facilities = ref<ServiceFacility[]>([]);
const categories = ['全部设施', '卫生间', '餐厅', '停车场', '游客服务中心', '医务室', '充电设施'];
const cityName = computed(() => store.experienceCityContext?.city?.cityName || '当前城市');
const contextKey = computed(() => store.experienceCityContext?.city?.cityKey
  || store.experienceCityContext?.adcode || cityName.value);
const heroStyle = computed(() => { const cover = store.experienceCityContext?.city?.coverImage; return { backgroundImage: `url(${cover || '/static/images/home-hero-scenic.webp'})` }; });
const visibleFacilities = computed(() => { const filtered = category.value === '全部设施' ? facilities.value : facilities.value.filter(item => item.type === category.value); return nearbyFirst.value ? [...filtered].sort((a, b) => (a.distance ?? Number.MAX_SAFE_INTEGER) - (b.distance ?? Number.MAX_SAFE_INTEGER)) : filtered; });
const sourceMode = computed(() => facilities.value.some(item => item.source === 'amap') ? 'amap' : facilities.value.some(item => item.source === 'local') ? 'local' : 'fallback');
const sourceLabel = computed(() => sourceMode.value === 'amap' ? '真实高德服务数据' : sourceMode.value === 'local' ? '景区本地服务资料' : 'Demo 降级数据');
const icons: Record<string, string> = { 卫生间: '洗', 餐厅: '餐', 停车场: 'P', 游客服务中心: 'i', 医务室: '医', 充电设施: '电' };
function iconFor(type: string): string { return icons[type] || '服'; }
function statusLabel(status: FacilityStatus): string { return ({ OPEN: '开放', BUSY: '营业中', ALL_DAY: '24小时', CLOSED: '暂时关闭', UNKNOWN: '现场确认' } as Record<FacilityStatus, string>)[status]; }
function distanceLabel(item: ServiceFacility): string { if (item.walkingTime != null) return `步行约 ${item.walkingTime} 分钟`; if (item.distance != null) return item.distance >= 1000 ? `约 ${(item.distance / 1000).toFixed(1)} 公里` : `约 ${item.distance} 米`; return '距离以现场位置为准'; }
function openFacility(item: ServiceFacility): void { if (item.latitude == null || item.longitude == null) return; uni.openLocation({ latitude: item.latitude, longitude: item.longitude, name: item.name, address: item.location }); }
async function reload(): Promise<void> { loading.value = true; error.value = ''; try { await initializeCityContext(); facilities.value = await loadServiceFacilities(store.experienceCityContext || null); } catch (value) { console.error('[DataSource] domain=services source=demo unavailable', value); facilities.value = []; error.value = ''; } finally { loading.value = false; } }
watch(contextKey, () => { void reload(); });
onMounted(() => { void reload(); });
</script>

<style scoped lang="scss">
