size:clamp(28px,3vw,42px);font-weight:800}.source-note{display:flex;align-items:center;gap:8px;color:#6d837a;font-size:11px}.source-dot{width:7px;height:7px;background:#c69a54;border-radius:50%}.source-dot--amap{background:#39a988}.source-dot--local{background:#587e6f}.facility-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.facility-card{display:flex;flex-direction:column;min-height:310px;padding:24px;color:#244d42;background:rgba(255,255,255,.82);border:1px solid rgba(24,72,59,.09);border-radius:21px;box-shadow:0 12px 35px rgba(30,69,57,.08);box-sizing:border-box;transition:transform .2s ease,box-shadow .2s ease}.facility-card:hover{transform:translateY(-4px);box-shadow:0 20px 44px rgba(30,69,57,.14)}.card-top{display:flex;justify-content:space-between;align-items:center}.facility-icon{display:grid;place-items:center;width:42px;height:42px;color:#fff;background:linear-gradient(145deg,#2e7966,#4a9a82);border-radius:13px;font-size:15px;font-weight:800}.status{padding:6px 9px;color:#3b725f;background:#e7f1eb;border-radius:999px;font-size:10px;font-weight:800}.status--closed{color:#9a574a;background:#f8e8e3}.status--all_day{color:#286d60;background:#dff3eb}.status--unknown{color:#786d52;background:#f4efdf}.facility-name{display:block;margin-top:20px;color:#173f35;font-size:20px;font-weight:800}.facility-description{display:block;min-height:45px;margin-top:9px;color:#6a8178;font-size:13px;line-height:1.7}.divider{height:1px;margin:19px 0;background:#e4ebe6}.detail{display:grid;grid-template-columns:20px 1fr;gap:6px;margin-top:8px;color:#5e776d;font-size:12px;line-height:1.5}.detail-icon{color:#40816e}.card-footer{display:flex;justify-content:space-between;gap:8px;margin-top:auto;padding-top:18px;color:#89a097;font-size:10px}.empty-state{display:grid;justify-items:center;gap:10px;padding:70px 20px;color:#72867e;text-align:center;background:rgba(255,255,255,.55);border-radius:20px}.empty-state--error{color:#9b5145}.empty-title{color:#315e51;font-size:18px;font-weight:800}.empty-state button{margin-top:10px;padding:10px 18px;color:#fff;background:#2e7966;border:0;border-radius:10px;font-size:12px}@media(max-width:1100px){.facility-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.filter-dock{padding:0 28px}}@media(max-width:700px){.services-page{padding-top:8px}.services-hero{height:350px;margin-top:8px}.hero-overlay{background:linear-gradient(90deg,rgba(248,248,239,.94),rgba(248,248,239,.58)),linear-gradient(0deg,rgba(242,245,237,.94),transparent 50%)}.hero-content{padding-top:58px}.hero-title{font-size:40px}.filter-dock{bottom:18px;display:grid;gap:10px;padding:0 20px}.nearby{width:fit-content}.facility-section{padding-top:38px}.section-head{display:grid}.facility-grid{grid-template-columns:1fr}.facility-card{min-height:290px}}
.services-hero{height:clamp(390px,38vw,430px)}.hero-content{gap:10px;max-width:650px;padding-top:clamp(58px,7vw,82px)}.hero-title{font-size:clamp(38px,4.4vw,58px)}.filter-dock{bottom:22px}.facility-grid>*{min-width:0}@media(max-width:700px){.services-hero{height:400px}.hero-content{padding-top:48px}.hero-title{font-size:38px}.filter-dock{bottom:16px}}
</style>
